function JYCPulse({ data }) { const published = data.events.filter(e => e.published && !e.archived); const upcoming = published.filter(e => eventState(e) !== 'past').length; const live = published.filter(e => eventState(e) === 'live').length; const now = new Date(); const todayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`; const today = published.filter(e => e.date === todayKey).length; const clubs = data.clubs.filter(c => c.published && c.status !== 'archived').length; const recruitment = data.clubs.filter(c => c.published && c.recruitment?.on).length; const hasActivity = upcoming || live || today || clubs || recruitment; if (!hasActivity) return null; return <section className="pulse-strip reveal"><div className="pulse-brand"><i /> <span>JYC PULSE</span></div><div className="pulse-items">{live ? <span>{live} live now</span> : today ? <span>{today} {today === 1 ? 'event' : 'events'} today</span> : upcoming ? <span>{upcoming} upcoming</span> : null}{clubs > 0 && <span>{clubs} active {clubs === 1 ? 'club' : 'clubs'}</span>}{recruitment > 0 && <span>{recruitment} recruitment {recruitment === 1 ? 'window' : 'windows'}</span>}</div></section> }
function NextMoment({ data }) { const events = data.events.filter(e => e.published && !e.archived && eventState(e) === 'upcoming').sort((a, b) => `${a.date} ${a.start || '00:00'}`.localeCompare(`${b.date} ${b.start || '00:00'}`)); const next = events[0]; const [left, setLeft] = useState(null); useEffect(() => { if (!next) return; const tick = () => { const target = new Date(`${next.date}T${next.start || '00:00'}`).getTime(); const diff = Math.max(0, target - Date.now()); setLeft({ d: Math.floor(diff / 86400000), h: Math.floor(diff / 3600000) % 24, m: Math.floor(diff / 60000) % 60 }); }; tick(); const id = setInterval(tick, 1000); return () => clearInterval(id) }, [next?.id, next?.date, next?.start]); if (!next || !left) return null; return <div className="next-moment-strip reveal"><div className="next-moment-copy"><i className="next-moment-live" /><div><strong>NEXT JYC MOMENT · {next.club || 'JYC'}</strong><span>{next.title} · {fmtDate(next.date)} · {next.start || 'TBA'} · {next.venue || 'Venue TBA'}</span></div></div><div className="next-moment-countdown" aria-label="Countdown to next JYC event"><b>{String(left.d).padStart(2, '0')}<small>days</small></b><b>{String(left.h).padStart(2, '0')}<small>hrs</small></b><b>{String(left.m).padStart(2, '0')}<small>min</small></b></div><button className="next-moment-action" onClick={() => window.location.assign('/events/' + next.id)}>View event →</button></div> }

